import Link from "next/link";
import { LearnerNav } from "@/components/learner-nav";
import { MockTrendChart } from "@/components/full-mock/history-chart";
import { requireUser } from "@/lib/auth/session";
import type { MockMode } from "@/lib/full-mock/blueprint";
import { compareCompatible, weakestPart } from "@/lib/full-mock/history";
import { getAdvancedMockHistory, getFullMockHistory, getMockHubReadiness } from "@/lib/full-mock/service";
import { getPreferences } from "@/lib/i18n/get-translations";
import { startAdvancedTargeting, startListeningPractice } from "@/app/practice/actions";

const modes = ["ALL", "LISTENING", "READING", "FULL"] as const;
const label = (mode: MockMode) => mode === "FULL" ? "Full Mock" : `${mode[0]}${mode.slice(1).toLowerCase()} Mock`;
const deltaText = (value: number) => `${value > 0 ? "+" : ""}${value} câu đúng`;

export default async function MockHistoryPage({ searchParams }: { searchParams: Promise<{ mode?: string }> }) {
  const user = await requireUser(); const requested = (await searchParams).mode; const selected = modes.includes(requested as typeof modes[number]) ? requested as typeof modes[number] : "ALL";
  const [advanced, basic, readiness, preferences] = await Promise.all([getAdvancedMockHistory(user.id), getFullMockHistory(user.id, 1), getMockHubReadiness(), getPreferences(user.id)]);
  if (!advanced) return <main className="min-h-screen bg-slate-50 px-4 py-6 text-slate-900"><div className="mx-auto max-w-4xl"><LearnerNav locale={preferences.interfaceLanguage}/><h1 className="mt-8 text-3xl font-black">Lịch sử thi thử</h1><section className="mt-6 rounded-2xl border bg-white p-6"><h2 className="text-xl font-black">So sánh lịch sử dành cho Premium</h2><p className="mt-2 text-slate-600">Kết quả đã hoàn thành vẫn được lưu. Nâng cấp Premium để xem xu hướng và so sánh theo Part.</p>{basic[0] ? <Link className="mt-4 inline-flex font-bold text-teal-700" href={`/full-mock/${basic[0].id}/results`}>Xem kết quả gần nhất</Link> : <Link className="mt-4 inline-flex font-bold text-teal-700" href="/full-mock">Bắt đầu thi thử</Link>}</section></div></main>;
  const filtered = selected === "ALL" ? advanced : advanced.filter((entry) => entry.mode === selected); const focusMode = (selected === "ALL" ? advanced[0]?.mode : selected) as MockMode | undefined; const compatible = focusMode ? advanced.filter((entry) => entry.mode === focusMode) : []; const latest = compatible[0]; const comparison = focusMode ? compareCompatible(advanced, focusMode) : null; const weak = latest ? weakestPart(latest) : null;
  const readyModes = [{mode:"LISTENING",ready:readiness.listening.ready},{mode:"READING",ready:readiness.reading.ready},{mode:"FULL",ready:readiness.full.ready}].filter(x=>x.ready);
  return <main className="min-h-screen bg-slate-50 px-4 py-6 text-slate-900"><div className="mx-auto max-w-6xl"><LearnerNav locale={preferences.interfaceLanguage}/><header className="mt-8"><p className="text-sm font-bold uppercase tracking-wider text-teal-700">Premium</p><h1 className="mt-2 text-3xl font-black sm:text-4xl">Lịch sử thi thử</h1><p className="mt-2 text-slate-600">Kết quả thô từ các bài đã hoàn thành; không phải điểm TOEIC quy đổi.</p></header>
    <nav className="mt-6 flex flex-wrap gap-2" aria-label="Lọc theo loại bài thi">{modes.map(mode => <Link aria-current={selected===mode?"page":undefined} className={`rounded-full px-4 py-2 font-bold ${selected===mode?"bg-slate-900 text-white":"border bg-white text-slate-700"}`} href={mode==="ALL"?"/full-mock/history":`/full-mock/history?mode=${mode}`} key={mode}>{mode === "ALL" ? "Tất cả" : mode[0]+mode.slice(1).toLowerCase()}</Link>)}</nav>
    {!advanced.length ? <section className="mt-8 rounded-3xl border bg-white p-8 text-center"><h2 className="text-2xl font-black">Chưa có lịch sử thi thử</h2><p className="mt-2 text-slate-600">Hoàn thành một bài thi thử để bắt đầu theo dõi kết quả theo thời gian.</p>{readyModes[0] ? <Link className="mt-5 inline-flex rounded-xl bg-teal-700 px-5 py-3 font-bold text-white" href="/full-mock">Bắt đầu thi thử</Link> : null}</section> : <>
      {latest ? <section className="mt-8 grid gap-4 lg:grid-cols-3"><article className="rounded-2xl border bg-white p-6"><p className="text-sm text-slate-500">Kết quả gần nhất · {label(latest.mode)}</p><p className="mt-2 text-4xl font-black">{latest.overall.correct} / {latest.overall.total}</p><p className="mt-2 text-sm text-slate-600">{new Date(latest.completedAt).toLocaleDateString("vi-VN")}</p></article><article className="rounded-2xl border bg-white p-6 lg:col-span-2"><h2 className="font-black">So với lần cùng loại trước</h2>{comparison ? <div className="mt-3 grid gap-3 sm:grid-cols-3">{latest.mode === "FULL" ? <><p>Listening<br/><strong>{comparison.previous.listening!.correct} → {comparison.current.listening!.correct} · {deltaText(comparison.listeningDelta!)}</strong></p><p>Reading<br/><strong>{comparison.previous.reading!.correct} → {comparison.current.reading!.correct} · {deltaText(comparison.readingDelta!)}</strong></p></> : null}<p>Tổng<br/><strong>{comparison.previous.overall.correct} → {comparison.current.overall.correct} · {deltaText(comparison.overallDelta)}</strong></p></div> : <p className="mt-3 text-slate-600">Hoàn thành thêm một bài cùng loại để bắt đầu so sánh.</p>}</article></section> : null}
      {latest ? <section className="mt-8 grid gap-6 lg:grid-cols-2"><article className="rounded-2xl border bg-white p-6"><h2 className="text-xl font-black">Hiệu suất theo thời gian · {label(latest.mode)}</h2><div className="mt-5"><MockTrendChart entries={compatible} mode={latest.mode}/></div></article><article className="rounded-2xl border bg-white p-6"><h2 className="text-xl font-black">Theo Part · lần gần nhất</h2><div className="mt-5 space-y-4">{latest.parts.map(part => <div key={part.part}><div className="flex justify-between gap-3"><strong>Part {part.part}</strong><span className="text-sm">{part.correct}/{part.total} · trả lời {part.answered}/{part.total} · {part.accuracy}%</span></div><div className="mt-2 h-3 overflow-hidden rounded-full bg-slate-100" role="progressbar" aria-label={`Part ${part.part}: ${part.accuracy}%`} aria-valuemin={0} aria-valuemax={100} aria-valuenow={part.accuracy}><div className="h-full bg-teal-600" style={{width:`${part.accuracy}%`}}/></div></div>)}</div></article></section> : null}
      {weak ? <section className="mt-8 rounded-2xl border border-teal-200 bg-white p-6"><p className="text-sm font-bold uppercase text-teal-700">Cần ưu tiên</p><h2 className="mt-1 text-2xl font-black">Part {weak.part} · {weak.accuracy}%</h2>{weak.part >= 5 ? <form action={startAdvancedTargeting} className="mt-4"><input type="hidden" name="targetingMode" value="target_weakness"/><input type="hidden" name="mode" value={`part_${weak.part}`}/><input type="hidden" name="questionCount" value="10"/><input type="hidden" name="source" value="recommended"/><button className="rounded-xl bg-teal-700 px-5 py-3 font-bold text-white">Luyện Part {weak.part}</button></form> : <form action={startListeningPractice} className="mt-4"><input type="hidden" name="part" value={weak.part}/><button className="rounded-xl bg-teal-700 px-5 py-3 font-bold text-white">Luyện Part {weak.part}</button></form>}</section> : null}
      <section className="mt-8"><h2 className="text-2xl font-black">Các bài gần đây</h2>{filtered.length ? <div className="mt-4 grid gap-3">{filtered.map(entry => <Link className="rounded-2xl border bg-white p-4 hover:border-teal-400" href={`/full-mock/${entry.runId}/results`} key={entry.runId}><span className="font-black">{label(entry.mode)}</span><span className="ml-3 text-slate-600">{new Date(entry.completedAt).toLocaleDateString("vi-VN")}</span><strong className="float-right">{entry.overall.correct}/{entry.overall.total}</strong></Link>)}</div> : <p className="mt-4 rounded-xl border border-dashed p-5 text-slate-600">Chưa có bài đã hoàn thành cho bộ lọc này.</p>}</section>
    </>}
  </div></main>;
}
